window.__POLYGON_SCRIPT_V2_PARTS__.push("                <div class=\"section__body\">\n                  <dl class=\"data-list\">\n                    <div class=\"data-row\"><dt>Сторона</dt><dd>${escapeHtml(unit.sideLabel)}</dd></div>\n                    <div class=\"data-row\"><dt>Тип</dt><dd>${escapeHtml(unit.type)}</dd></div>\n                    <div class=\"data-row\"><dt>Здоровье</dt><dd>${unit.health}%</dd></div>\n                    <div class=\"data-row\"><dt>Подавление</dt><dd>${unit.suppression}%</dd></div>\n                  </dl>\n                </div>\n              </section>\n              <div class=\"meter\"><div class=\"meter__head\"><span>Состояние</span><strong>${unit.health}%</strong></div><div class=\"meter__track\"><div class=\"meter__fill\" style=\"--value:${unit.health}%\"></div></div></div>\n              <div class=\"meter\"><div class=\"meter__head\"><span>Подавление</span><strong>${unit.suppression}%</strong></div><div class=\"meter__track\"><div class=\"meter__fill\" style=\"--value:${unit.suppression}%\"></div></div></div>\n            </div>`;\n        }\n        if (state.inspector === 'overview') return blank('Обзор');\n        if (state.inspector === 'memory') return blank('Память');\n        if (state.inspector === 'danger') return blank('Опасность');\n        if (state.inspector === 'stealth') return blank('Скрытность');\n        if (state.inspector === 'positions') return blank('Позиции');\n        if (state.inspector === 'weapon') {\n          return `\n            <div class=\"panel-scroll\">\n              <section class=\"section\">\n                <div class=\"section__head\"><span class=\"section__title\">Вооружение</span></div>\n                <div class=\"section__body\">\n                  <dl class=\"data-list\">\n                    <div class=\"data-row\"><dt>Оружие</dt><dd>${escapeHtml(unit.weapon)}</dd></div>\n                    <div class=\"data-row\"><dt>Боеприпасы</dt><dd>${unit.ammo}</dd></div>\n                  </dl>\n                </div>\n              </section>\n            </div>`;\n        }\n        return '';\n      }\n\n      function renderInspector() {\n        const unit = selectedUnit();\n        if (!unit) {\n          els.rightPanelTitle.textContent = 'Юнит не выбран';\n          els.rightPanelContent.innerHTML = `\n            <div class=\"empty-state inspector-empty\">\n              <div>\n                <div class=\"empty-state__icon\">◎</div>\n                <strong>Выберите юнита на карте</strong>\n                <p>Здесь появится информация о его состоянии. Характеристики в этой панели не изменяются.</p>\n              </div>\n            </div>`;\n          return;\n        }\n        els.rightPanelTitle.textContent = unit.name;\n        els.rightPanelContent.innerHTML = `\n          <div class=\"inspector-unit-head\">\n            <div class=\"inspector-unit-avatar\">${escapeHtml(unit.short)}</div>\n            <div><div class=\"inspector-unit-name\">${escapeHtml(unit.name)}</div><div class=\"inspector-unit-meta\">${escapeHtml(unit.type)} · ${escapeHtml(unit.sideLabel)}</div></div>\n          </div>\n          ${inspectorBody(unit)}`;\n      }\n\n      function selectUnit(unitId, options = {}) {\n        if (!state.units.some(unit => unit.id === unitId)) return;\n        state.selectedUnitId = unitId;\n        renderUnits();\n        renderInspector();\n        if (state.workspace === 'unit-editor') renderWorkspace();\n        if (!options.silent) toast(`Выбран: ${selectedUnit().name}`);\n      }\n\n      function setInspectorTab(tab) {\n        const valid = ['info', 'overview', 'memory', 'danger', 'stealth', 'positions', 'weapon'];\n        if (!valid.includes(tab)) return;\n        state.inspector = tab;\n        [...els.inspectorTabs.querySelectorAll('[data-inspector]')].forEach(button => {\n          button.classList.toggle('is-active', button.dataset.inspector === tab);\n        });\n        renderInspector();\n      }\n\n      function setMapAction(action, label) {\n        state.mapAction = action;\n        state.mapActionLabel = label;\n        els.activeActionText.textContent = label;\n        els.activeAction.classList.add('is-visible');\n        els.mapSurface.style.cursor = 'crosshair';\n        closeContextMenu();\n      }\n\n      function cancelMapAction() {\n        state.mapAction = null;\n        state.mapActionLabel = '';\n        els.activeAction.classList.remove('is-visible');\n        els.mapSurface.style.cursor = '';\n      }\n\n      function mapPositionFromEvent(event) {\n        const rect = els.mapSurface.getBoundingClientRect();\n        return {\n          x: Math.max(0, Math.min(100, ((event.clientX - rect.left) / rect.width) * 100)),\n          y: Math.max(0, Math.min(100, ((event.clientY - rect.top) / rect.height) * 100))\n        };\n      }\n\n      function applyMapAction(event) {\n        if (!state.mapAction) return false;\n        const position = mapPositionFromEvent(event);\n        if (state.mapAction === 'place-unit') {\n          const index = state.units.length + 1;\n          const preset = archetypeProfileSets['Стрелок'];\n          const unit = {\n            id: `unit-${Date.now()}`,\n            name: `Новый юнит ${index}`,\n            short: `Ю${index}`,\n            side: 'blue',\n            sideLabel: 'Синие',\n            type: 'Стрелок',\n            archetype: 'Стрелок',\n            ...preset,\n            pose: 'stand',\n            state: 'Готов',\n            x: position.x,\n            y: position.y,\n            heading: 0,\n            health: 100,\n            suppression: 0,\n            fatigue: 0,\n            morale: 100,\n            awarenessSeconds: 5,\n            injuries: 'Нет',\n            visibility: 'Не определена',\n            weapon: 'Винтовка Мосина',\n            loadedAmmo: 5,\n            reserveAmmo: 25,\n            ammo: 30\n          };\n          state.units.push(unit);\n          state.selectedUnitId = unit.id;\n          state.unitListOpen = false;\n          renderUnits();\n          renderInspector();\n          renderWorkspace();\n          toast('Юнит создан и выбран для настройки');\n        } else if (state.mapAction === 'move-selected-unit') {\n          const unit = selectedUnit();\n          if (unit) { unit.x = position.x; unit.y = position.y; renderUnits(); renderInspector(); renderWorkspace(); toast('Юнит перемещён'); }\n        } else if (state.mapAction === 'rotate-selected-unit') {\n          const unit = selectedUnit();\n          if (unit) {\n            const dx = position.x - unit.x;\n            const dy = position.y - unit.y;\n            unit.heading = Math.round(Math.atan2(dy, dx) * 180 / Math.PI + 90);\n            renderUnits(); renderWorkspace(); toast(`Направление: ${unit.heading}°`);\n          }\n        } else {\n          const typeMap = {\n            'add-point': ['point', 'Программная точка'],\n            'add-area': ['area', 'Программная область'],\n            'add-target': ['target', 'Цель'],\n            'paint-relief': ['terrain', 'Рельеф'],\n            'paint-ground': ['terrain', 'Покрытие'],\n            'paint-roads': ['terrain', 'Дорога'],\n            'paint-buildings': ['terrain', 'Здание'],\n            'paint-objects': ['terrain', 'Предмет']\n          };\n          const [type, label] = typeMap[state.mapAction] || ['point', 'Маркер'];\n          state.experiment.markers.push({ id: `marker-${Date.now()}`, type, label, ...position });\n          renderMarkers();\n          toast(`${label} добавлена на карту`);\n        }\n        cancelMapAction();\n        return true;\n      }\n\n      function contextItems() {\n        if (state.workspace === 'program') {\n          return [\n            ['＋', 'Добавить точку', 'add-point'],\n            ['◯', 'Добавить область', 'add-area'],\n            ['⌖', 'Выбрать цель', 'add-target']\n          ];\n        }\n        if (state.workspace === 'map-editor') {\n          if (state.mapSubmode === 'field') return [['↔', 'Настроить размер поля', 'focus-field-size']];\n          return [['✦', `Работать: ${mapSubmodeNames[state.mapSubmode]}`, `paint-${state.mapSubmode}`]];\n        }\n        if (state.workspace === 'unit-editor') {\n          return [\n            ['＋', 'Создать юнита здесь', 'place-unit'],\n            ['◎', 'Выбрать ближайшего юнита', 'select-nearest']\n          ];\n        }\n        return [['·', 'Сведения о точке', 'point-info']];\n      }\n\n      function openMapContextMenu(eventOrX, maybeY) {\n        let x;\n        let y;\n        if (typeof eventOrX === 'object') {\n          eventOrX.preventDefault();\n          x = eventOrX.clientX;\n          y = eventOrX.clientY;\n        } else {\n          x = eventOrX;\n          y = maybeY;\n        }\n        const items = contextItems();\n        els.contextMenu.innerHTML = `\n          <div class=\"context-menu__title\">${escapeHtml(workspaceNames[state.workspace])}</div>\n          ${items.map(([icon, label, action]) => `<button type=\"button\" data-context-action=\"${action}\"><span class=\"context-menu__icon\">${icon}</span>${escapeHtml(label)}</button>`).join('')}`;\n        els.contextMenu.classList.add('is-open');\n        const width = 228;\n        const height = 50 + items.length * 36;\n        els.contextMenu.style.left = `${Math.max(8, Math.min(window.innerWidth - width - 8, x))}px`;\n        els.contextMenu.style.top = `${Math.max(66, Math.min(window.innerHeight - height - 8, y))}px`;\n      }\n\n      function closeContextMenu() {\n        els.contextMenu.classList.remove('is-open');\n      }\n\n      function handleContextAction(action) {\n        closeContextMenu();\n        if (action === 'focus-field-size') {\n          setWorkspaceMode('map-editor', { silent: true });\n          state.mapSubmode = 'field';\n          renderWorkspace();\n          els.leftPanel.classList.remove('is-collapsed');\n          state.leftCollapsed = false;\n          setTimeout(() => document.getElementById('mapWidth')?.focus(), 0);\n");
